
WITH m AS (SELECT COALESCE(SUM(total_orders),0)::numeric AS total_orders, COALESCE(SUM(total_order_items),0)::numeric AS total_order_items, COALESCE(SUM(total_units_sold),0)::numeric AS total_units_sold, COALESCE(SUM(total_recorded_sales),0)::numeric AS total_recorded_sales, COALESCE(SUM(total_discounts),0)::numeric AS total_discounts, COALESCE(SUM(total_net_item_value),0)::numeric AS total_net_item_value FROM analytics.vw_monthly_sales), k AS (SELECT total_orders::numeric, total_order_items::numeric, total_units_sold::numeric, total_recorded_sales, total_discounts, total_net_item_value, average_order_value, discount_rate_pct FROM analytics.vw_kpi_overview) SELECT 'total_orders' AS metric, k.total_orders AS overall_kpi, m.total_orders AS monthly_rollup, m.total_orders-k.total_orders AS difference FROM m CROSS JOIN k UNION ALL SELECT 'total_order_items', k.total_order_items, m.total_order_items, m.total_order_items-k.total_order_items FROM m CROSS JOIN k UNION ALL SELECT 'total_units_sold', k.total_units_sold, m.total_units_sold, m.total_units_sold-k.total_units_sold FROM m CROSS JOIN k UNION ALL SELECT 'total_recorded_sales', k.total_recorded_sales, m.total_recorded_sales, m.total_recorded_sales-k.total_recorded_sales FROM m CROSS JOIN k UNION ALL SELECT 'total_discounts', k.total_discounts, m.total_discounts, m.total_discounts-k.total_discounts FROM m CROSS JOIN k UNION ALL SELECT 'total_net_item_value', k.total_net_item_value, m.total_net_item_value, m.total_net_item_value-k.total_net_item_value FROM m CROSS JOIN k UNION ALL SELECT 'average_order_value', k.average_order_value, ROUND(m.total_net_item_value/NULLIF(m.total_orders,0),2), ROUND(m.total_net_item_value/NULLIF(m.total_orders,0),2)-k.average_order_value FROM m CROSS JOIN k UNION ALL SELECT 'discount_rate_pct', k.discount_rate_pct, ROUND(100.0*m.total_discounts/NULLIF(m.total_recorded_sales,0),2), ROUND(100.0*m.total_discounts/NULLIF(m.total_recorded_sales,0),2)-k.discount_rate_pct FROM m CROSS JOIN k ORDER BY metric;
